CREATE TABLE projects (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(id));
CREATE TABLE project_repositories (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, repository_url TEXT NOT NULL, branch TEXT NOT NULL, script_root TEXT NOT NULL, run_command TEXT NOT NULL, runner_config_version TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE environments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, name TEXT NOT NULL, base_url TEXT NOT NULL, health_check_config TEXT NOT NULL, secret_ref TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(project_id,name), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE requirement_snapshots (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, file_name TEXT NOT NULL, object_key TEXT NOT NULL, manual_version TEXT, summary TEXT, uploaded_by TEXT NOT NULL, uploaded_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE ai_generations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, requirement_snapshot_id TEXT NOT NULL, model TEXT NOT NULL, prompt_version TEXT NOT NULL, raw_result TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,requirement_snapshot_id) REFERENCES requirement_snapshots(project_id,id));
CREATE TABLE test_points (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, requirement_snapshot_id TEXT, name TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('AI','HUMAN_CREATE','HUMAN_EDIT')), status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,requirement_snapshot_id) REFERENCES requirement_snapshots(project_id,id));
CREATE TABLE functional_cases (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, case_code TEXT NOT NULL, module TEXT NOT NULL, scenario TEXT NOT NULL, precondition TEXT, steps TEXT NOT NULL DEFAULT '[]', expected_result TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL, test_type TEXT NOT NULL, automation_recommendation INTEGER NOT NULL DEFAULT 0 CHECK(automation_recommendation IN (0,1)), status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','CONFIRMED','RETIRED')), current_version_no INTEGER, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(project_id,case_code), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE functional_case_versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, functional_case_id TEXT NOT NULL, version_no INTEGER NOT NULL, module TEXT NOT NULL, scenario TEXT NOT NULL, precondition TEXT, steps TEXT NOT NULL, expected_result TEXT NOT NULL, priority TEXT NOT NULL, test_type TEXT NOT NULL, automation_recommendation INTEGER NOT NULL CHECK(automation_recommendation IN (0,1)), change_reason TEXT NOT NULL, confirmed_by TEXT NOT NULL, confirmed_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(functional_case_id,version_no), FOREIGN KEY(project_id,functional_case_id) REFERENCES functional_cases(project_id,id));
CREATE TABLE case_change_logs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, functional_case_id TEXT NOT NULL, field TEXT NOT NULL, old_value TEXT, new_value TEXT, source TEXT NOT NULL CHECK(source IN ('AI','HUMAN_CREATE','HUMAN_EDIT')), actor_id TEXT NOT NULL, reason TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,functional_case_id) REFERENCES functional_cases(project_id,id));
CREATE TABLE automation_cases (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, case_code TEXT NOT NULL, functional_case_id TEXT NOT NULL, level TEXT NOT NULL, tags TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(review_status IN ('DRAFT','PENDING_REVIEW','APPROVED','REJECTED')), execution_status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(execution_status IN ('DRAFT','PENDING_IMPLEMENTATION','EXECUTABLE','NEEDS_UPDATE','DISABLED')), current_version_no INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(project_id,case_code), FOREIGN KEY(project_id,functional_case_id) REFERENCES functional_cases(project_id,id));
CREATE TABLE automation_draft_designs (automation_case_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, design TEXT NOT NULL, UNIQUE(project_id,automation_case_id), FOREIGN KEY(project_id,automation_case_id) REFERENCES automation_cases(project_id,id));
CREATE TABLE automation_case_versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, automation_case_id TEXT NOT NULL, version_no INTEGER NOT NULL, functional_case_version_id TEXT NOT NULL, project_repository_id TEXT NOT NULL, design TEXT NOT NULL, script_path TEXT, git_sha TEXT, reviewed_by TEXT, reviewed_at TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(automation_case_id,version_no), FOREIGN KEY(project_id,automation_case_id) REFERENCES automation_cases(project_id,id), FOREIGN KEY(project_id,functional_case_version_id) REFERENCES functional_case_versions(project_id,id), FOREIGN KEY(project_id,project_repository_id) REFERENCES project_repositories(project_id,id));
CREATE TABLE automation_impacts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, functional_case_version_id TEXT NOT NULL, automation_case_id TEXT NOT NULL, impact_type TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','RESOLVED','DISMISSED')), resolved_by TEXT, resolved_at TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,functional_case_version_id) REFERENCES functional_case_versions(project_id,id), FOREIGN KEY(project_id,automation_case_id) REFERENCES automation_cases(project_id,id));
CREATE TABLE test_suites (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, name TEXT NOT NULL, selection_rule TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(project_id,name), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE test_suite_members (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, test_suite_id TEXT NOT NULL, automation_case_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(test_suite_id,automation_case_id), FOREIGN KEY(project_id,test_suite_id) REFERENCES test_suites(project_id,id), FOREIGN KEY(project_id,automation_case_id) REFERENCES automation_cases(project_id,id));
CREATE TABLE run_batches (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, environment_id TEXT NOT NULL, name TEXT, release_version TEXT, trigger_type TEXT NOT NULL, triggered_by TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','RUNNING','COMPLETED','ENVIRONMENT_BLOCKED','CANCELLED')), selection_snapshot TEXT NOT NULL, execution_snapshot TEXT, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,environment_id) REFERENCES environments(project_id,id));
CREATE TABLE run_case_results (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, run_batch_id TEXT NOT NULL, automation_case_version_id TEXT NOT NULL, functional_case_version_id TEXT NOT NULL, case_snapshot TEXT NOT NULL, script_sha TEXT NOT NULL, final_status TEXT NOT NULL DEFAULT 'NOT_RUN' CHECK(final_status IN ('NOT_RUN','RUNNING','PASSED','FAILED','SKIPPED','BLOCKED')), error_summary TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,run_batch_id) REFERENCES run_batches(project_id,id), FOREIGN KEY(project_id,automation_case_version_id) REFERENCES automation_case_versions(project_id,id), FOREIGN KEY(project_id,functional_case_version_id) REFERENCES functional_case_versions(project_id,id));
CREATE TABLE run_attempts (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, run_case_result_id TEXT NOT NULL, attempt_no INTEGER NOT NULL CHECK(attempt_no BETWEEN 1 AND 2), status TEXT NOT NULL CHECK(status IN ('NOT_RUN','RUNNING','PASSED','FAILED','SKIPPED','BLOCKED')), started_at TEXT NOT NULL, finished_at TEXT, error_summary TEXT, UNIQUE(project_id,id), UNIQUE(run_case_result_id,attempt_no), FOREIGN KEY(project_id,run_case_result_id) REFERENCES run_case_results(project_id,id));
CREATE TABLE environment_health (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, run_batch_id TEXT NOT NULL, login_page_status TEXT NOT NULL, key_api_status TEXT NOT NULL, conclusion TEXT NOT NULL, checked_at TEXT NOT NULL, UNIQUE(project_id,id), UNIQUE(run_batch_id), FOREIGN KEY(project_id,run_batch_id) REFERENCES run_batches(project_id,id));
CREATE TABLE failure_triage (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, run_case_result_id TEXT NOT NULL, ai_category TEXT CHECK(ai_category IN ('PRODUCT','SCRIPT','ENVIRONMENT','TEST_DATA','NETWORK_OR_THIRD_PARTY','UNKNOWN')), confidence REAL, summary TEXT, confirmed_category TEXT CHECK(confirmed_category IN ('PRODUCT','SCRIPT','ENVIRONMENT','TEST_DATA','NETWORK_OR_THIRD_PARTY','UNKNOWN')), confirmed_by TEXT, confirmed_at TEXT, UNIQUE(project_id,id), UNIQUE(run_case_result_id), FOREIGN KEY(project_id,run_case_result_id) REFERENCES run_case_results(project_id,id));
CREATE TABLE evidence_files (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, run_case_result_id TEXT NOT NULL, kind TEXT NOT NULL, object_key TEXT NOT NULL, redacted INTEGER NOT NULL DEFAULT 0 CHECK(redacted IN (0,1)), expires_at TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,run_case_result_id) REFERENCES run_case_results(project_id,id));
CREATE TABLE manual_executions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, functional_case_version_id TEXT NOT NULL, run_batch_id TEXT, status TEXT NOT NULL CHECK(status IN ('NOT_RUN','RUNNING','PASSED','FAILED','SKIPPED','BLOCKED')), actor_id TEXT NOT NULL, note TEXT, evidence_link TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id,functional_case_version_id) REFERENCES functional_case_versions(project_id,id), FOREIGN KEY(project_id,run_batch_id) REFERENCES run_batches(project_id,id));
CREATE TABLE release_waivers (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, release_version TEXT NOT NULL, failed_case_reference TEXT NOT NULL, reason TEXT NOT NULL, actor_id TEXT NOT NULL, expires_at TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,id), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE INDEX idx_functional_cases_project_status ON functional_cases(project_id,status);
CREATE INDEX idx_automation_cases_project_status ON automation_cases(project_id,execution_status);
CREATE INDEX idx_evidence_files_project_expiry ON evidence_files(project_id,expires_at);
